"""Adapter between PyAcornDFS and the py8dis disassembler.

This is the only module that knows py8dis exists. py8dis keeps its state in
module-level globals, parses sys.argv when `commands` is imported and prints
the listing from go(), so each disassembly runs in a fresh Python subprocess
from a generated control script. That keeps state from leaking between runs in
the GUI, stops a py8dis crash taking the GUI down, and needs no py8dis changes.

py8dis is found via the PY8DIS_PATH environment variable (the directory that
holds commands.py), falling back to the external/py8dis git submodule.
"""

import os
import subprocess
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path

PY8DIS_ENV = "PY8DIS_PATH"
DEFAULT_TIMEOUT = 120
LISTING_EXT = ".6502"  # BeebASM source, the extension the Beeb VSC extension expects
SCRIPT_EXT = ".py"

_REPO_ROOT = Path(__file__).resolve().parents[2]
_SUBMODULE_PACKAGE = _REPO_ROOT / "external" / "py8dis" / "py8dis"


class DisasmError(RuntimeError):
    """py8dis could not be run or failed."""

    def __init__(self, message, stderr=""):
        super().__init__(message)
        self.stderr = stderr


@dataclass
class DisasmResult:
    """Outcome of one disassembly."""

    listing: str  # BeebASM source text
    control_script: str  # the py8dis control script that produced it
    stderr: str  # anything py8dis wrote to stderr (warnings)
    listing_path: Path | None = None
    script_path: Path | None = None
    binary_path: Path | None = None


def find_py8dis():
    """Return the py8dis package directory (holding commands.py), or None."""
    candidates = []
    if os.environ.get(PY8DIS_ENV):
        candidates.append(Path(os.environ[PY8DIS_ENV]))
    candidates.append(_SUBMODULE_PACKAGE)
    for candidate in candidates:
        if (candidate / "commands.py").is_file():
            return candidate.resolve()
    return None


def is_available():
    """True if py8dis can be found."""
    return find_py8dis() is not None


def split_address(value):
    """Split an 18-bit DFS load/exec value into (6502 address, high bits).

    The high bits are non-zero for I/O processor addresses (&FFxxxx), which
    read_file_info() expands to &FFFFxxxx.
    """
    return value & 0xFFFF, value >> 16


IO_PROCESSOR = 0xFFFF  # high bits of an I/O processor address after read_file_info()
MEMORY_TOP = 0x10000


def describe_address(value):
    """Human readable form of a DFS address, noting the I/O processor."""
    address, high = split_address(value)
    if high == IO_PROCESSOR:
        return f"&{value:08X} (I/O processor &{address:04X})"
    if high:
        return f"&{value:05X} (high bits &{high:X}, &{address:04X})"
    return f"&{address:04X}"


def fit_length(load_addr, length):
    """Number of bytes that fit in the 64K address space from load_addr."""
    return min(length, MEMORY_TOP - split_address(load_addr)[0])


def safe_name(name):
    """Make a DFS name usable as a host filename."""
    cleaned = "".join("_" if c in '/\\:*?"<>|' or ord(c) < 32 else c for c in name)
    return cleaned.strip() or "UNNAMED"


def choose_entry(load_addr, exec_addr, length):
    """Pick the trace entry point: the exec address if it lies in the file."""
    load16, _ = split_address(load_addr)
    exec16, _ = split_address(exec_addr)
    if load16 <= exec16 < load16 + length:
        return exec16
    return load16


def make_control_script(binary_name, load_addr, exec_addr, length, name):
    """Return the text of a py8dis control script for one DFS file."""
    load16, _ = split_address(load_addr)
    fitted = fit_length(load_addr, length)
    entry16 = choose_entry(load_addr, exec_addr, fitted)
    exec_note = describe_address(exec_addr)
    if entry16 != split_address(exec_addr)[0]:
        exec_note += " is outside the file, tracing from the load address"
    header = f"{name}: load {describe_address(load_addr)}, exec {exec_note}, length &{length:X}"
    if fitted < length:
        header += f"; truncated to &{fitted:X} bytes at &FFFF"
    script_name = binary_name.removesuffix(".trunc")
    return f'''# py8dis control script for {name}, generated by PyAcornDFS.
# {header}
# Refine by hand and re-run with:
#   PYTHONPATH=/path/to/py8dis/py8dis python3 "{script_name}{SCRIPT_EXT}" > "{script_name}{LISTING_EXT}"
import os as _os

_here = _os.path.dirname(_os.path.abspath(__file__))

from commands import *
import acorn

load(0x{load16:04X}, _os.path.join(_here, {binary_name!r}), "6502")
acorn.bbc()
comment(0x{load16:04X}, {header!r})
entry(0x{entry16:04X})
go()
'''


def disassemble(data, load_addr, exec_addr, name, out_dir=None, timeout=DEFAULT_TIMEOUT):
    """Disassemble `data` with py8dis and return a DisasmResult.

    With `out_dir`, the binary (NAME), the control script (NAME.py) and the
    listing (NAME.6502) are written there side by side; otherwise a temporary
    directory is used and nothing is kept.
    """
    if not data:
        raise DisasmError(f"{name} is empty")
    package_dir = find_py8dis()
    if package_dir is None:
        raise DisasmError(f"py8dis not found: set {PY8DIS_ENV} or run 'git submodule update --init'")

    base_name = safe_name(name)
    fitted = fit_length(load_addr, len(data))
    # A truncated copy gets its own name so it never replaces a full "Save" of NAME.
    binary_name = base_name if fitted == len(data) else base_name + ".trunc"
    script = make_control_script(binary_name, load_addr, exec_addr, len(data), name)

    with tempfile.TemporaryDirectory(prefix="pyacorndfs-") as temp_dir:
        work_dir = Path(out_dir) if out_dir is not None else Path(temp_dir)
        work_dir.mkdir(parents=True, exist_ok=True)
        binary_path = work_dir / binary_name
        script_path = work_dir / (base_name + SCRIPT_EXT)
        binary_path.write_bytes(bytes(data[:fitted]))
        script_path.write_text(script)

        env = dict(os.environ)
        env["PYTHONPATH"] = os.pathsep.join(filter(None, (str(package_dir), env.get("PYTHONPATH"))))
        try:
            proc = subprocess.run(
                [sys.executable, str(script_path), "--beebasm"],
                cwd=work_dir,
                env=env,
                capture_output=True,
                text=True,
                timeout=timeout,
            )
        except subprocess.TimeoutExpired as error:
            raise DisasmError(f"py8dis timed out after {timeout}s on {name}", error.stderr or "") from error
        if proc.returncode != 0:
            raise DisasmError(f"py8dis failed on {name} (exit {proc.returncode})", proc.stderr)

        result = DisasmResult(listing=proc.stdout, control_script=script, stderr=proc.stderr)
        if out_dir is not None:
            listing_path = work_dir / (base_name + LISTING_EXT)
            listing_path.write_text(proc.stdout)
            result.listing_path = listing_path
            result.script_path = script_path
            result.binary_path = binary_path
        return result
